const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim();
let n = parseInt(input, 10) + 1;
const d = 1000000007;

let g = Array.from({ length: n }, () => Array(n).fill(1));

for (let i = 1; i < n; i++) {
    g[i][0] = g[i - 1][i - 1];
    for (let j = 1; j <= i; j++) {
        g[i][j] = (g[i][j - 1] + g[i - 1][j - 1]) % d;
    }
}

console.log(((g[n - 1][n - 1] - g[n - 1][0]) % d + d) % d);

